    static int stateIndex(int x, int y, int dir, int lev, int far) {
        return (((((x * SIZE + y) * 8 + dir) * 32 + lev) * 6) + far);
    }

    static long encode(int x, int y, int dir, int lev, int far) {
        return (long) x
                | ((long) y << 9)
                | ((long) dir << 18)
                | ((long) lev << 21)
                | ((long) far << 27);
    }

    static int[] rotate(int dir) {
        switch (dir) {
            case UP:
                return new int[]{UPLEFT, UPRIGHT};
            case DOWN:
                return new int[]{DOWNLEFT, DOWNRIGHT};
            case LEFT:
                return new int[]{UPLEFT, DOWNLEFT};
            case RIGHT:
                return new int[]{UPRIGHT, DOWNRIGHT};
            case UPLEFT:
