        visited.set(MAX * SIZE + MAX);

        int ans = 1;

        while (!queue.isEmpty()) {
            long state = queue.poll();

            int x = (int) (state & 511);
            int y = (int) ((state >>> 9) & 511);
            int dir = (int) ((state >>> 18) & 7);
            int lev = (int) ((state >>> 21) & 63);
            int far = (int) ((state >>> 27) & 63);

            int position = x * SIZE + y;
            if (!visited.get(position)) {
                visited.set(position);
                ans++;
            }

            if (lev == n + 1) {
                continue;
            }

