                int nextX = x + DX[dir];
                int nextY = y + DY[dir];
                int nextFar = far + 1;
                int index = stateIndex(nextX, nextY, dir, lev, nextFar);

                if (!marked.get(index)) {
                    marked.set(index);
                    queue.add(encode(nextX, nextY, dir, lev, nextFar));
                }
