                grow();
            }
            data[(head + size) % data.length] = value;
            size++;
        }

        long poll() {
            long value = data[head];
            head = (head + 1) % data.length;
            size--;
            return value;
        }

        boolean isEmpty() {
            return size == 0;
        }

        private void grow() {
            long[] newData = new long[data.length << 1];
            for (int i = 0; i < size; i++) {
                newData[i] = data[(head + i) % data.length];
            }
            data = newData;
            head = 0;
        }
